fortsetzung_rechnerische_schlussbilanz <- function(bereinigte_restmasse=NULL, ersatzschuld_ehegatte=NULL, anrechnung_abkoemmlinge=NULL, gezahlte_abfindungen=NULL, bilanznachweis=NULL) {
 r <- .geld(bereinigte_restmasse);a <- .geld(ersatzschuld_ehegatte);b <- .geld(anrechnung_abkoemmlinge);c <- .geld(gezahlte_abfindungen);.text(bilanznachweis,'bilanznachweis')
 m <- .addieren(.addieren(r,a),.addieren(b,c));h <- .dividieren(m,.bruch(2));s <- .subtrahieren(h,a);k <- .subtrahieren(.subtrahieren(h,b),c);rest <- .subtrahieren(a,h)
 if(.vergleichen(rest,.bruch(0))<0) rest <- .bruch(0)
 wert <- list(rechenmasse=.bruchteile(m),halbteil_vor_anrechnung=.bruchteile(h),ehegattensaldo=.bruchteile(s),abkoemmlingssaldo=.bruchteile(k),abkoemmlingssaldo_vor_abfindungsanrechnung=.bruchteile(.subtrahieren(h,b)),ueberschiessende_ersatzpflicht_ehegatte=.bruchteile(rest),persoenliche_ersatzpflicht_abkoemmlinge_nach_1476_absatz2_satz2=.bruchteile(.bruch(0)))
 eingaben <- list(bereinigte_restmasse=bereinigte_restmasse, ersatzschuld_ehegatte=ersatzschuld_ehegatte, anrechnung_abkoemmlinge=anrechnung_abkoemmlinge, gezahlte_abfindungen=gezahlte_abfindungen, bilanznachweis=bilanznachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_FORTSETZUNG_RECHNERISCHE_SCHLUSSBILANZ",eingaben,list(list(operation="Qualifizierte Bilanzposten addieren, halbieren und seitengerecht anrechnen; persoenliche ueberschiessende Ersatzpflicht nur beim ueberlebenden Ehegatten ausweisen.")),eingaben)
 ergebnis$hinweise <- list("Rechnerische Verbindung1498/1476 mit1500/1501: Restmasse plus beide qualifizierten Anrechnungsposten plus tatsaechlich gezahlte Abfindungen halbieren; eigene Lasten jeweils auf die betreffende Haelfte anrechnen. Negative Abkoemmlingssalden begruenden nach1498 gerade keine ueberschiessende persoenliche1476II2-Ersatzpflicht. Nur die ueberschiessende Ersatzschuld des ueberlebenden Ehegatten wird als solche ausgewiesen. Positive Salden sind rechnerische Bilanzpositionen, keine Zusage realisierbarer oder sofort faelliger Barauszahlung; gegenstaendliche Haftung, Deckung, Bewertung und Uneinbringlichkeit gesondert bestimmen. Personenverteilung1503I, Vorempfaenge1503II und ausschliesslich Beguenstigte treffende Lasten1503III/1511III2 anschliessend ohne Doppelabzug normgerecht verbinden. Keine automatische Anrechnung aller Lasten proportional auf jeden Abkoemmling. Keine abschliessende Abwicklung beliebiger Insolvenz-/Haftungskonstellationen.")
 ergebnis
}
